m=1000
L={'P1':3000,'P2':600,'P3':1200}
r={k:v/m for k,v in L.items()}
def s(o):
    t=0;w={}
    for p in o:
        w[p]=t;t+=r[p]
    return w,t
w1,k1=s(['P1','P2','P3'])
w2,k2=s(['P2','P3','P1'])
a1=sum(w1.values())/3
a2=sum(w2.values())/3
for x in [r['P1'],r['P2'],r['P3'],a1,a2,k1]:print(f'{x:g}')
